from django.contrib import admin
from django.urls import reverse
from django.utils.html import format_html
from simple_history.admin import SimpleHistoryAdmin

from .models import Client, Contact

# ------------------------------------------------------------------
# Historical models are auto-generated by HistoricalRecords().
# Fetching them from the source model's `.history.model` — this is
# available as soon as the models module is fully loaded, which it
# is by the time admin.py runs.
# ------------------------------------------------------------------
HistoricalClient  = Client.history.model
HistoricalContact = Contact.history.model


# ==================================================================
# CLIENT
# ==================================================================
class ContactInline(admin.TabularInline):
    model = Contact
    extra = 0
    fields = ("first_name", "surname", "email")
    show_change_link = True


@admin.register(Client)
class ClientAdmin(SimpleHistoryAdmin):
    list_display    = ("name", "code", "contact_count", "is_delinked", "created_at")
    list_filter     = ("is_delinked",)
    search_fields   = ("name", "code")
    readonly_fields = ("code", "created_at", "delinked_at")
    inlines         = [ContactInline]

    fieldsets = (
        ("Client", {"fields": ("name", "code", "logo")}),
        ("Status", {
            "fields": ("is_delinked", "delinked_at", "created_at"),
            "classes": ("collapse",),
        }),
    )

    @admin.display(description="Contacts")
    def contact_count(self, obj):
        return obj.contacts.count()


# ==================================================================
# CONTACT
# ==================================================================
@admin.register(Contact)
class ContactAdmin(SimpleHistoryAdmin):
    list_display        = ("first_name", "surname", "email", "client", "created_at")
    list_filter         = ("client",)
    search_fields       = ("first_name", "surname", "email")
    autocomplete_fields = ("client",)
    readonly_fields     = ("created_at",)


# ==================================================================
# AUDIT LOG — global read-only view of historical rows
# ==================================================================
class HistoryReadOnlyAdmin(admin.ModelAdmin):
    """Read-only viewer for historical models."""

    list_per_page = 50
    actions = None

    def has_add_permission(self, request, obj=None):       return False
    def has_change_permission(self, request, obj=None):    return False
    def has_delete_permission(self, request, obj=None):    return False
    def has_module_permission(self, request):              return request.user.is_staff

    # ----------------------------------------------------------
    # Shared display helpers
    # ----------------------------------------------------------
    @admin.display(description="Type", ordering="history_type")
    def history_type_badge(self, obj):
        mapping = {
            "+": ("Created", "#198754"),
            "~": ("Updated", "#b51c10"),
            "-": ("Deleted", "#6c757d"),
        }
        label, color = mapping.get(obj.history_type, ("—", "#adb5bd"))
        return format_html(
            '<span style="display:inline-block;padding:.15rem .5rem;'
            'border-radius:999px;background:{};color:#fff;font-size:.75rem;">{}</span>',
            color, label,
        )

    @admin.display(description="Changes")
    def changed_fields(self, obj):
        prev = obj.prev_record
        if prev is None:
            return "—"
        diff = obj.diff_against(prev)
        if not diff.changes:
            return "—"
        parts = []
        for change in diff.changes:
            old = change.old if change.old not in (None, "") else "∅"
            new = change.new if change.new not in (None, "") else "∅"
            parts.append(
                f'<strong>{change.field}</strong>: '
                f'<span style="color:#6c757d;">{old}</span> → '
                f'<span style="color:#b51c10;">{new}</span>'
            )
        return format_html("<br>".join(parts))

    @admin.display(description="Changed by", ordering="history_user")
    def changed_by(self, obj):
        return obj.history_user.get_username() if obj.history_user else "system"


# ------------------------------------------------------------------
# HISTORICAL CLIENT — register the auto-generated model directly
# ------------------------------------------------------------------
@admin.register(HistoricalClient)
class HistoricalClientAdmin(HistoryReadOnlyAdmin):
    list_display   = ("name", "code", "history_type_badge",
                      "changed_fields", "history_date", "changed_by")
    list_filter    = ("history_type", "history_user", "is_delinked")
    search_fields  = ("name", "code")
    date_hierarchy = "history_date"
    ordering       = ("-history_date",)

    @admin.display(description="Client")
    def live_client_link(self, obj):
        try:
            live = Client.objects.get(pk=obj.id)
            url = reverse("admin:clientTrackerApp_client_change", args=[live.pk])
            return format_html('<a href="{}">{}</a>', url, live.name)
        except Client.DoesNotExist:
            return obj.name


# ------------------------------------------------------------------
# HISTORICAL CONTACT —
# ------------------------------------------------------------------
@admin.register(HistoricalContact)
class HistoricalContactAdmin(HistoryReadOnlyAdmin):
    list_display   = ("first_name", "surname", "email", "client",
                      "history_type_badge", "changed_fields",
                      "history_date", "changed_by")
    list_filter    = ("history_type", "history_user")
    search_fields  = ("first_name", "surname", "email")
    date_hierarchy = "history_date"
    ordering       = ("-history_date",)